int main() {
    int A, B;
    if (!(cin >> A >> B)) return 0;

    int a = ((A - 1) % 3 + 1) % 3;
    int b = ((B - 1) % 3 + 1) % 3;
    if (b == a) b = (a + 1) % 3;

    bool used[3] = {false, false, false};
    used[a] = true;
    used[b] = true;
    for (int c = 0; c < 3; c++) {
        if (!used[c]) {
            cout << c << "\n";
            break;
        }
    }
    return 0;
}
